/bin/bash -lc "python - <<'PY'
import urllib.request
for url in ['https://openrouter.ai/docs/guides/routing/model-variants/routers','https://openrouter.ai/api/v1/models']:
    try:
        with urllib.request.urlopen(url, timeout=20) as r:
            body = r.read().decode()
        if url.endswith('/models'):
            import json
            models = json.loads(body)['data']
            matches = [m for m in models if 'decision' in json.dumps(m).lower()]
            for m in matches:
                print(m['id'], m.get('description','')[:1800])
        else:
            print(url, body[:250])
    except Exception as exc:
        print(type(exc).__name__, str(exc))
PY"

